; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: neogeo (SNK Neo Geo (68000)), starts in turbo mode
; ============================================================

			org 0

NTC_RAMEND	equ $10C000		; the end of the RAM the variables and arrays are in (;@ramend)
NTC_A16ADD	equ $110000		; (;@a16) added to a 16 bit address once sign extended: where the RAM's 64K is (0: $FF8000 on, the Mega Drive)
NTC_A16		macro			; an address register loaded from a 16 bit address (movea.w): to the RAM it means
			ifne NTC_A16ADD
			adda.l #NTC_A16ADD, \1
			endif
			endm
;## ntc_md_vectors ntc_ng_boot
; the cartridge's vectors (the BIOS's routines for the exceptions, as every cartridge has them)
; and the Neo Geo header (the compiler puts this first, at 0)
			dc.l $0010F300				; the supervisor stack
			dc.l $00C00402				; reset: the BIOS
			dc.l $00C00408, $00C0040E, $00C00414, $00C0041A	; bus, address, illegal, zero divide
			dc.l $00C0041A, $00C0041A, $00C0041A, $00C00420	; CHK, TRAPV, privilege, trace
			dc.l $00C00426, $00C00426					; line 1010, 1111
			dcb.l 3, $FFFFFFFF			; 12-14
			dc.l $00C0042C				; 15 uninitialised interrupt
			dcb.l 8, $FFFFFFFF			; 16-23
			dc.l $00C00432				; 24 spurious
			dc.l ntc_ng_vbl				; 25 level 1: VBlank
			dc.l ntc_ng_timer			; 26 level 2: the timer
			dc.l ntc_ng_rte				; 27 level 3
			dcb.l 4, ntc_ng_rte			; 28-31
			dcb.l 32, $FFFFFFFF			; 32-63
; the header ($100): test/ngbuild.js puts in the NGH number and the name
			dc.b "NEO-GEO", 0
			dc.w $0C1C					; $108 the NGH number (3100: not $999, which the emulators take for V-Liner)
			dc.l $00100000				; $10A the program's size
			dc.l $0010E800				; $10E an MVS's backup RAM (none used)
			dc.w 0						; $112 its size
			dc.b 1						; $114 the eye-catcher: the game's (USER request 1, which goes straight back)
			dc.b 0						; $115 its first tile
			dc.l ntc_ng_dip, ntc_ng_dip, ntc_ng_dip	; $116 the soft DIPs: Japan, the US, Europe
			dc.w $4EF9					; $122 USER: jmp abs.l (written out: 6 bytes each, at
			dc.l ntc_ng_user			;      the header's fixed places)
			dc.w $4EF9					; $128 PLAYER_START
			dc.l ntc_ng_rts
			dc.w $4EF9					; $12E DEMO_END
			dc.l ntc_ng_rts
			dc.w $4EF9					; $134 COIN_SOUND
			dc.l ntc_ng_rts
			dcb.b 70, $FF				; $13A
			dc.w 0						; $180
			dc.l ntc_ng_scode			; $182 the security code
ntc_ng_scode:
			dc.w $7600, $4A6D, $0A14, $6600, $003C, $206D, $0A04, $3E2D
			dc.w $0A08, $13C0, $0030, $0001, $3210, $0C01, $00FF, $671A
			dc.w $3028, $0002, $B02D, $0ACE, $6610, $3028, $0004, $B02D
			dc.w $0ACF, $6606, $B22D, $0AD0, $6708, $5088, $51CF, $FFD4
			dc.w $3607, $4E75, $206D, $0A04, $3E2D, $0A08, $3210, $E049
			dc.w $0C01, $00FF, $671A, $3010, $B02D, $0ACE, $6612, $3028
			dc.w $0002, $E048, $B02D, $0ACF, $6606, $B22D, $0AD0, $6708
			dc.w $5888, $51CF, $FFD8, $3607, $4E75
ntc_ng_dip:	dc.b "NTC BASIC       "		; the name the BIOS shows (16)
			dc.b $FF, $FF, $FF, $FF		; no time DIPs
			dc.b $FF, $FF				; no number DIPs
			dcb.b 10, 0					; no choice DIPs
			even

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; Main.bas 13: Cls
			dc.l kw_cls

			; Main.bas 14: Print "VB self test 5"
			dc.l kw_printstrvar, str0
			dc.l kw_printnl

			; Main.bas 17: v = 5
			dc.l kw_ltov, 5, var_v

			; Main.bas 18: #asm
			dc.l asm_0_18

			; Main.bas 24: Chk v, 105
			dc.l p_chk_c, var_v, lit_105

			; Main.bas 27: Chk AddAsm(30, 12), 42
			dc.l p_addasm_c, lit_30, lit_12
			dc.l kw_vtov, var_addasm_addasm, tmp0
			dc.l p_chk_c, tmp0, lit_42

			; Main.bas 28: Chk Times3(7), 21
			dc.l p_times3_c, lit_7
			dc.l kw_vtov, var_times3_times3, tmp0
			dc.l p_chk_c, tmp0, lit_21

			; Main.bas 29: Chk CountBits(255), 8
			dc.l p_countbits_c, lit_255
			dc.l kw_vtov, var_countbits_countbits, tmp0
			dc.l p_chk_c, tmp0, lit_8

			; Main.bas 30: Chk CountBits(&H8001), 2
			dc.l p_countbits_c, lit_m32767
			dc.l kw_vtov, var_countbits_countbits, tmp0
			dc.l p_chk_c, tmp0, lit_2

			; Main.bas 31: n = 9
			dc.l kw_ltov, 9, var_n

			; Main.bas 32: Twice n
			dc.l p_twice_c, var_n

			; Main.bas 33: Chk n, 18
			dc.l p_chk_c, var_n, lit_18

			; Main.bas 34: tbl(2) = 77
			dc.l kw_ltov, 77, arr_tbl+4

			; Main.bas 35: Chk ThirdOf(tbl), 77
			dc.l p_thirdof_c, ad_arr_tbl
			dc.l kw_vtov, var_thirdof_thirdof, tmp0
			dc.l p_chk_c, tmp0, lit_77

			; Main.bas 38: v = Inp(&HF500)
			dc.l kw_inp, lit_m2816, var_v

			; Main.bas 39: Chk (v >= 0) And (v <= 255), -1
			dc.l kw_scpgevl, var_v, 0
			dc.l kw_ftov, tmp0
			dc.l kw_scplevl, var_v, 255
			dc.l kw_ftov, tmp1
			dc.l kw_andvv, tmp0, tmp1, tmp0
			dc.l p_chk_c, tmp0, lit_m1

			; Main.bas 40: Out &H7F00, &H10
			dc.l kw_out, lit_32512, lit_16

			; Main.bas 43: Debug.Assert v >= 0
			dc.l kw_scpgevl, var_v, 0
			dc.l kw_goto_iftrue, as1_ok
			dc.l kw_printnl0
			dc.l kw_printstrvar, str1
			dc.l kw_printnl
			dc.l kw_printnl0
			dc.l kw_printstrvar, str2
			dc.l kw_waitkey
			dc.l kw_stop
as1_ok:

			; Main.bas 46: h1 = Pool.Open(10)
			dc.l p_pool_open_c, lit_10
			dc.l kw_vtov, var_pool_open_open, var_h1

			; Main.bas 47: h2 = Pool.Open(20)
			dc.l p_pool_open_c, lit_20
			dc.l kw_vtov, var_pool_open_open, var_h2

			; Main.bas 48: Chk h1, 0
			dc.l p_chk_c, var_h1, lit_0

			; Main.bas 49: Chk h2, 1
			dc.l p_chk_c, var_h2, lit_1

			; Main.bas 50: Pool.Add h1, 5
			dc.l p_pool_add_c, var_h1, lit_5

			; Main.bas 51: Pool.Add h2, 7
			dc.l p_pool_add_c, var_h2, lit_7

			; Main.bas 52: Pool.Add h1, 1
			dc.l p_pool_add_c, var_h1, lit_1

			; Main.bas 53: Chk Pool.Value(h1), 16
			dc.l p_pool_value_c, var_h1
			dc.l kw_vtov, var_pool_value_value, tmp0
			dc.l p_chk_c, tmp0, lit_16

			; Main.bas 54: Chk Pool.Value(h2), 27
			dc.l p_pool_value_c, var_h2
			dc.l kw_vtov, var_pool_value_value, tmp0
			dc.l p_chk_c, tmp0, lit_27

			; Main.bas 55: Chk Pool.Uses(h1), 2
			dc.l p_pool_uses_c, var_h1
			dc.l kw_vtov, var_pool_uses_uses, tmp0
			dc.l p_chk_c, tmp0, lit_2

			; Main.bas 56: Chk Pool.MAXSLOTS, 4
			dc.l p_chk_c, lit_4, lit_4

			; Main.bas 57: Pool.Close h1
			dc.l p_pool_close_c, var_h1

			; Main.bas 58: Chk Pool.Open(30), 0
			dc.l p_pool_open_c, lit_30
			dc.l kw_vtov, var_pool_open_open, tmp0
			dc.l p_chk_c, tmp0, lit_0

			; Main.bas 59: Chk Pool.Open(1), 2
			dc.l p_pool_open_c, lit_1
			dc.l kw_vtov, var_pool_open_open, tmp0
			dc.l p_chk_c, tmp0, lit_2

			; Main.bas 60: Chk Pool.Open(1), 3
			dc.l p_pool_open_c, lit_1
			dc.l kw_vtov, var_pool_open_open, tmp0
			dc.l p_chk_c, tmp0, lit_3

			; Main.bas 61: Chk Pool.Open(1), -1
			dc.l p_pool_open_c, lit_1
			dc.l kw_vtov, var_pool_open_open, tmp0
			dc.l p_chk_c, tmp0, lit_m1

			; Main.bas 63: Print
			dc.l kw_printnl

			; Main.bas 64: Print t; " tests, "; bad; " failed"
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str3
			dc.l kw_printint, var_bad
			dc.l kw_printstrvar, str4
			dc.l kw_printnl

			; Main.bas 65: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str2
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub chk (turbo mode)
; ============================================================

p_chk:

			; Main.bas 68: t = t + 1
			dc.l kw_inc, var_t

			; Main.bas 69: Print t; ":";
			dc.l kw_printint, var_t
			dc.l kw_printstrvar, str5

			; Main.bas 70: If got = want Then
			dc.l kw_cpeqvv, var_chk_got, var_chk_want
			dc.l kw_goto_iffalse, if2_1

			; Main.bas 71: Print "ok ";
			dc.l kw_printstrvar, str6

			; Main.bas 72: Else
			dc.l if2_e_go
if2_1:

			; Main.bas 73: Print "FAIL("; got; ") ";
			dc.l kw_printstrvar, str7
			dc.l kw_printint, var_chk_got
			dc.l kw_printstrvar, str8

			; Main.bas 74: bad = bad + 1
			dc.l kw_inc, var_bad

			; Main.bas 75: End If
if2_e:
			dc.l p_chk_r

; ============================================================
; function addasm (turbo mode)
; ============================================================

p_addasm:

			; Main.bas 79: #asm
			dc.l asm_0_79
			dc.l p_addasm_r

; ============================================================
; function times3 (turbo mode)
; ============================================================

p_times3:

			; Main.bas 88: Times3 = x
			dc.l kw_vtov, var_times3_x, var_times3_times3

			; Main.bas 89: #asm
			dc.l asm_0_89
			dc.l p_times3_r

; ============================================================
; function countbits (turbo mode)
; ============================================================

p_countbits:

			; Main.bas 101: #asm
			dc.l asm_0_101
			dc.l p_countbits_r

; ============================================================
; sub twice (turbo mode)
; ============================================================

p_twice:

			; Main.bas 120: #asm
			dc.l asm_0_120
			dc.l p_twice_r

; ============================================================
; function thirdof (turbo mode)
; ============================================================

p_thirdof:

			; Main.bas 130: #asm
			dc.l asm_0_130
			dc.l p_thirdof_r

; ============================================================
; function open (turbo mode)
; ============================================================

p_pool_open:

			; Pool.cls 16: Dim h As Integer

			; Pool.cls 17: For h = 0 To MAXSLOTS - 1
			dc.l kw_ztov, var_pool_open_h
for3_t:

			; Pool.cls 18: If mSlots(h).used = 0 Then
			dc.l kw_aget, arr_pool_mslots_used, var_pool_open_h, tmp0
			dc.l kw_cpeqvl, tmp0, 0
			dc.l kw_goto_iffalse, if4_1

			; Pool.cls 19: mSlots(h).used = -1
			dc.l kw_asetl, arr_pool_mslots_used, var_pool_open_h, -1

			; Pool.cls 20: mSlots(h).total = start
			dc.l kw_aset, arr_pool_mslots_total, var_pool_open_h, var_pool_open_start

			; Pool.cls 21: mSlots(h).count = 0
			dc.l kw_asetl, arr_pool_mslots_count, var_pool_open_h, 0

			; Pool.cls 22: mOpen = mOpen + 1
			dc.l kw_inc, var_pool_mopen

			; Pool.cls 23: Open = h
			dc.l kw_vtov, var_pool_open_h, var_pool_open_open

			; Pool.cls 24: Exit Function
			dc.l p_pool_open_r

			; Pool.cls 25: End If
if4_1:

			; Pool.cls 26: Next
			dc.l kw_next1l, var_pool_open_h, 3, for3_t
for3_e:

			; Pool.cls 27: Open = -1
			dc.l kw_ltov, -1, var_pool_open_open
			dc.l p_pool_open_r

; ============================================================
; sub add (turbo mode)
; ============================================================

p_pool_add:

			; Pool.cls 31: mSlots(h).total = mSlots(h).total + n
			dc.l kw_aget, arr_pool_mslots_total, var_pool_add_h, tmp1
			dc.l kw_add, tmp1, var_pool_add_n, tmp1
			dc.l kw_aset, arr_pool_mslots_total, var_pool_add_h, tmp1

			; Pool.cls 32: Bump h
			dc.l p_pool_bump_c, var_pool_add_h
			dc.l p_pool_add_r

; ============================================================
; function value (turbo mode)
; ============================================================

p_pool_value:

			; Pool.cls 36: Value = mSlots(h).total
			dc.l kw_aget, arr_pool_mslots_total, var_pool_value_h, var_pool_value_value
			dc.l p_pool_value_r

; ============================================================
; function uses (turbo mode)
; ============================================================

p_pool_uses:

			; Pool.cls 40: Uses = mSlots(h).count
			dc.l kw_aget, arr_pool_mslots_count, var_pool_uses_h, var_pool_uses_uses
			dc.l p_pool_uses_r

; ============================================================
; sub close (turbo mode)
; ============================================================

p_pool_close:

			; Pool.cls 44: mSlots(h).used = 0
			dc.l kw_asetl, arr_pool_mslots_used, var_pool_close_h, 0

			; Pool.cls 45: mOpen = mOpen - 1
			dc.l kw_dec, var_pool_mopen
			dc.l p_pool_close_r

; ============================================================
; sub bump (turbo mode)
; ============================================================

p_pool_bump:

			; Pool.cls 49: mSlots(h).count = mSlots(h).count + 1
			dc.l kw_aget, arr_pool_mslots_count, var_pool_bump_h, tmp1
			dc.l kw_inc, tmp1
			dc.l kw_aset, arr_pool_mslots_count, var_pool_bump_h, tmp1
			dc.l p_pool_bump_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if2_e_go:			lea if2_e, sp
			rts

p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_addasm_c:		; call addasm
			movea.l (sp)+, a0		; a
			move.w (a0), var_addasm_a
			movea.l (sp)+, a0		; b
			move.w (a0), var_addasm_b
			clr.w var_addasm_addasm
			move.l sp, p_addasm_rs
			lea p_addasm, sp
			rts
p_addasm_r:		; end of addasm
			movea.l p_addasm_rs, sp
			rts
p_times3_c:		; call times3
			movea.l (sp)+, a0		; x
			move.w (a0), var_times3_x
			clr.w var_times3_times3
			move.l sp, p_times3_rs
			lea p_times3, sp
			rts
p_times3_r:		; end of times3
			movea.l p_times3_rs, sp
			rts
p_countbits_c:		; call countbits
			movea.l (sp)+, a0		; x
			move.w (a0), var_countbits_x
			clr.w var_countbits_countbits
			move.l sp, p_countbits_rs
			lea p_countbits, sp
			rts
p_countbits_r:		; end of countbits
			movea.l p_countbits_rs, sp
			rts
p_twice_c:		; call twice
			movea.l (sp)+, a0		; n
			move.l a0, p_twice_a0
			move.w (a0), var_twice_n
			move.l sp, p_twice_rs
			lea p_twice, sp
			rts
p_twice_r:		; end of twice
			movea.l p_twice_a0, a1
			move.w var_twice_n, (a1)
			movea.l p_twice_rs, sp
			rts
p_thirdof_c:		; call thirdof
			movea.l (sp)+, a0		; a() descriptor
			lea pa_thirdof_a, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_thirdof_thirdof
			move.l sp, p_thirdof_rs
			lea p_thirdof, sp
			rts
p_thirdof_r:		; end of thirdof
			movea.l p_thirdof_rs, sp
			rts
p_pool_open_c:		; call open
			movea.l (sp)+, a0		; start
			move.w (a0), var_pool_open_start
			clr.w var_pool_open_open
			clr.w var_pool_open_h
			move.l sp, p_pool_open_rs
			lea p_pool_open, sp
			rts
p_pool_open_r:		; end of open
			movea.l p_pool_open_rs, sp
			rts
p_pool_add_c:		; call add
			movea.l (sp)+, a0		; h
			move.w (a0), var_pool_add_h
			movea.l (sp)+, a0		; n
			move.w (a0), var_pool_add_n
			move.l sp, p_pool_add_rs
			lea p_pool_add, sp
			rts
p_pool_add_r:		; end of add
			movea.l p_pool_add_rs, sp
			rts
p_pool_value_c:		; call value
			movea.l (sp)+, a0		; h
			move.w (a0), var_pool_value_h
			clr.w var_pool_value_value
			move.l sp, p_pool_value_rs
			lea p_pool_value, sp
			rts
p_pool_value_r:		; end of value
			movea.l p_pool_value_rs, sp
			rts
p_pool_uses_c:		; call uses
			movea.l (sp)+, a0		; h
			move.w (a0), var_pool_uses_h
			clr.w var_pool_uses_uses
			move.l sp, p_pool_uses_rs
			lea p_pool_uses, sp
			rts
p_pool_uses_r:		; end of uses
			movea.l p_pool_uses_rs, sp
			rts
p_pool_close_c:		; call close
			movea.l (sp)+, a0		; h
			move.w (a0), var_pool_close_h
			move.l sp, p_pool_close_rs
			lea p_pool_close, sp
			rts
p_pool_close_r:		; end of close
			movea.l p_pool_close_rs, sp
			rts
p_pool_bump_c:		; call bump
			movea.l (sp)+, a0		; h
			move.w (a0), var_pool_bump_h
			move.l sp, p_pool_bump_rs
