;## kw_inp
;kw_inp, <portvar>, <dest>  - Inp(n): the byte at $A10000 + n (the I/O area: 1 the
;  version, 3 / 5 / 7 the ports' data, 9 / B / D their control)
kw_inp:
			movea.l (sp)+, a0
			move.w (a0), d0
			ext.l d0
			addi.l #$A10000, d0
			movea.l d0, a0
			moveq #0, d0
			move.b (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_out
;kw_out, <portvar>, <valuevar>  - Out n, v: the byte at $A10000 + n
kw_out:
			movea.l (sp)+, a0
			move.w (a0), d0
			ext.l d0
			addi.l #$A10000, d0
			movea.l (sp)+, a1
			movea.l d0, a0
			move.b 1(a1), (a0)
			rts

